function formatHour(h: number): string {
  if (!Number.isFinite(h)) return '—';
  const hour = ((Math.trunc(h) % 24) + 24) % 24;
  if (hour === 0) return '12a';
  if (hour === 12) return '12p';
  return hour < 12 ? `${hour}a` : `${hour - 12}p`;
}

